import{_ as i,a0 as l,w as o,s as u,ao as s,I as e,a1 as n,A as r,x as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"SBackup: 一個Linux下的簡單備份軟件 | LCTT x X-CMD","titleTemplate":false,"description":"SBackup: 一個Linux下的簡單備份軟件 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"SBackup: 一個Linux下的簡單備份軟件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"SBackup: 一個Linux下的簡單備份軟件 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/SBackup--A Simple Backup Solution For Your Linux Desktop","title":"SBackup: 一個Linux下的簡單備份軟件","tag":"201312","desc":""},"relativePath":"201312/SBackup--A Simple Backup Solution For Your Linux Desktop.md","filePath":"[post].md"}'),c={name:"201312/SBackup--A Simple Backup Solution For Your Linux Desktop.md"};function d(k,p,h,m,g,S){const t=l("Link");return o(),u("div",null,[p[13]||(p[13]=s(`<h1 id="sbackup-一個linux下的簡單備份軟件" tabindex="-1">SBackup: 一個Linux下的簡單備份軟件 <a class="header-anchor" href="#sbackup-一個linux下的簡單備份軟件" aria-label="Permalink to “SBackup: 一個Linux下的簡單備份軟件”">​</a></h1><p><strong>SBackup</strong> 是一個簡單易用的開源備份軟件。它可以備份任意文件或者文件夾的一部分。所有的配置文件可以通過 Gnome 界面進行訪問。文件和路徑可以直接通過正則表達式進行添加和排除。它支持本地備份和遠程備份。雖然它看起來簡單，但是它有着許多常見的高級備份功能。</p><h3 id="特點" tabindex="-1">特點 <a class="header-anchor" href="#特點" aria-label="Permalink to “特點”">​</a></h3><p>SBackup 可以完成以下工作</p><ul><li>可以創建壓縮和未壓縮的備份</li><li>可以把未壓縮的備份分割成多份文件</li><li>支持多份備份配置。每個人都可以根據自己的需求創建並修改自己的配置文件，但是不能刪除默認配置文件</li><li>有多種選項，如日誌、郵件通知、以狀態圖標的形式展現和提醒</li><li>支持計劃任務備份和手動備份</li><li>可以備份到本地（如硬盤），也可以備份到遠程（如通過 FTP 訪問 NAS）</li></ul><h3 id="在-ubuntu、linux-mint-和-debian-上安裝-sbackup" tabindex="-1">在 Ubuntu、Linux Mint 和 Debian 上安裝 SBackup <a class="header-anchor" href="#在-ubuntu、linux-mint-和-debian-上安裝-sbackup" aria-label="Permalink to “在 Ubuntu、Linux Mint 和 Debian 上安裝 SBackup”">​</a></h3><p>SBackup 可在 Ubuntu、Linux Mint 和 Debian 的默認倉庫中獲得，所以只要運行以下命令即可安裝</p><pre><code>sudo apt-get install sbackup
</code></pre><h3 id="運行-sbackup" tabindex="-1">運行 SBackup <a class="header-anchor" href="#運行-sbackup" aria-label="Permalink to “運行 SBackup”">​</a></h3><p>通過 Dash 或者 Menu 打開 SBackup</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Menu_0011.jpg" alt=""></p><p>將會看到如下界面</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Simple-Backup-Suite_002.jpg" alt=""></p><h3 id="sbackup-配置" tabindex="-1">SBackup 配置 <a class="header-anchor" href="#sbackup-配置" aria-label="Permalink to “SBackup 配置”">​</a></h3><p>最初的 SBackup 沒有任何用户自定義的配置文件，只有默認的配置文件。需要注意的是，用户不能刪除默認的配置文件。若要創建一個新的配置文件，點擊 Tools -&gt; Profile Manager，將看到如下窗口</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Simple-Backup-Suite_003.jpg" alt=""></p><p>單擊 Add 來創建新配置文件，例子的文件用“sk”來命名</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Simple-Backup-Suite_004.jpg" alt=""></p><p>現在已經創建了新的配置文件。若要設置配置，先選擇配置文件，再單擊 Edit</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Configuration-Profile-Manager_005.jpg" alt=""></p><p>現在看到 SBackup 的配置文件已經被切換到“sk”</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Simple-Backup-Suite_006.jpg" alt=""></p><p>當然，也可以根據不同人的需求來修改默認配置文件</p><p><strong>注意事項</strong>：如果你用普通用户運行 SBackup，計劃任務備份不能生效，你需要用 root 用户來運行。如上圖所示，因為我是以普通用户運行 Sbackup，所以 Schedule 選項是灰色不可選中狀態。</p><p>在本教程中，我將以 root 權限運行 SBackup，並且使用的是<strong>默認配置</strong></p><p>打開終端，運行以下命令來以 root 權限運行 SBackup</p><pre><code>sudo sbackup-config-gtk
</code></pre><p>上面的命令將以 root 權限打開默認配置的 SBackup</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Simple-Backup-Suite_001.jpg" alt=""></p><h4 id="general選項卡" tabindex="-1">General選項卡 <a class="header-anchor" href="#general選項卡" aria-label="Permalink to “General選項卡”">​</a></h4><p>在 General 選項內，你可以選擇多久進行一次完整備份，默認是7天。每7天 SBackup 將會進行一次完整的備份。你也可以選擇備份的壓縮格式。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Simple-Backup-Suite_0021.jpg" alt=""></p><h4 id="include選項卡" tabindex="-1">Include選項卡 <a class="header-anchor" href="#include選項卡" aria-label="Permalink to “Include選項卡”">​</a></h4><p>這個選項不需要解釋太多，你可以添加 SBackup 要備份的文件或目錄。這裏可以選擇備份單獨的文件或者完整的目錄，我刪除了所有的目錄僅僅保留了“Resume”</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Simple-Backup-Suite_0031.jpg" alt=""></p><h4 id="exclude選項卡" tabindex="-1">Exclude選項卡 <a class="header-anchor" href="#exclude選項卡" aria-label="Permalink to “Exclude選項卡”">​</a></h4><p>如同 Include 選項，我們可以選擇備份時排除的文檔和目錄，只需要選擇要排除的文檔和目錄的路徑即可。在默認配置下，/media, /var/run/, /var/cache/, /var/spool/ 和 /vat/tmp/ 目錄均被排除</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Simple-Backup-Suite_0041.jpg" alt=""></p><p>更進一步的是，你可以增加備份時排除文件的類型，像 mp3 和 avi 等等。在默認配置下，mp3, avi, mpeg, mkv, ogg 和 iso 是被排除不被備份的。如果你想備份這些文件，只要選中然後點擊 remove。當然，如果要排除其他類型的文件，只需要點擊 add 然後增加。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Simple-Backup-Suite_005.jpg" alt=""></p><p>在默認配置下，SBackup 不會備份.gvfs, .thumbnails, .Trash 和 .cache 這些文件夾</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Simple-Backup-Suite_0061.jpg" alt=""></p><p>同時你也可以在備份時根據文件大小來排除某些文檔和文件夾，這裏我排除了體積超過100MB 的文檔和文件夾。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Simple-Backup-Suite_0071.jpg" alt=""></p><h4 id="destination選項卡" tabindex="-1">Destination選項卡 <a class="header-anchor" href="#destination選項卡" aria-label="Permalink to “Destination選項卡”">​</a></h4><p>在這裏你可以選擇備份存放的路徑，正如我之前提到的，你可以把備份的文檔或文件夾存放在硬盤或者遠程的 FTP 或 NAS。這裏我將把備份保存在 /home/sk/My Backup 目錄下。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Simple-Backup-Suite_019.jpg" alt=""></p><p><strong>提示:</strong> 在備份前確認目錄有足夠的空間保存備份文件</p><h4 id="schedule選項卡" tabindex="-1">Schedule選項卡 <a class="header-anchor" href="#schedule選項卡" aria-label="Permalink to “Schedule選項卡”">​</a></h4><p>在這個選項中，你可以設定具體的備份時間。點擊 <strong>Simple</strong> 選項，可以按每小時、每日、每週、每月來設置你的計劃備份時間。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Simple-Backup-Suite_010.jpg" alt=""></p><p>如果你擅長使用命令列來計劃任務，則可以使用 cron 來操作。當你開啓每日備份計劃時，cron 命令在 <strong>/etc/cron.daily/</strong> 目錄中創建計劃文件</p><pre><code>sudo ls -l /etc/cron.daily/sbackup
</code></pre><p>示例的輸出顯示</p><pre><code>lrwxrwxrwx 1 root root 33 Nov  8 15:34 /etc/cron.daily/sbackup -&gt; /usr/share/sbackup/sbackup-launch
</code></pre><h4 id="purging選項卡" tabindex="-1">Purging選項卡 <a class="header-anchor" href="#purging選項卡" aria-label="Permalink to “Purging選項卡”">​</a></h4><p>在這個選項裏，可以刪除超過一定時間的備份文件。在默認配置下，超過30天的備份文件將被刪除。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Simple-Backup-Suite_0111.jpg" alt=""></p><h4 id="report選項卡" tabindex="-1">Report選項卡 <a class="header-anchor" href="#report選項卡" aria-label="Permalink to “Report選項卡”">​</a></h4><p>Report 是最後一個選項卡，在這裏你可以設置接收備份完成通知的郵箱。輸入你的郵箱ID、SMTP服務地址、郵箱用户名、密碼後，點擊 Test mail settings。需要留意的是，在測試郵箱設置前，點擊工具欄中的Save Configuration按鈕保存你的配置。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Simple-Backup-Suite_0121.jpg" alt=""></p><p>你將在完成測試郵箱設置後看到 “Test Successful” 字樣。</p><h3 id="開始備份" tabindex="-1">開始備份 <a class="header-anchor" href="#開始備份" aria-label="Permalink to “開始備份”">​</a></h3><p>點擊 SBackup 工具欄上的 <strong>Make Backup now button</strong> 按鈕立即開始備份。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Selection_015.jpg" alt=""></p><p>彈出一個窗口，點擊 Yes 開始創建備份文件。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/sbackup-config-gtk_024.jpg" alt=""></p><p>現在備份的進程已經在後台開始運行，你可以通過在通知欄上的狀態顯示來監視備份的進程。</p><p>完成備份之後，關閉 SBackup ，並且確認備份文件保存在指定的目錄。例子中我保存的目錄是/home/sk/My Backup。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Selection_020.jpg" alt=""></p><h3 id="恢復文件" tabindex="-1">恢復文件 <a class="header-anchor" href="#恢復文件" aria-label="Permalink to “恢復文件”">​</a></h3><p>在終端中運行命令</p><pre><code>sudo sbackup-restore-gtk
</code></pre><p>在 SBackup 的恢復窗口，選擇可用的備份日期和快照，在 Restoration Management 面板中選擇任意一個要恢復的文件，單擊 <strong>restore</strong> 保存到默認位置或者單擊 <strong>restore as</strong> 保存到指定的位置。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Simple-Backup-Suite_023.jpg" alt=""></p><p>現在文件已經從備份中恢復，就這麼簡單。</p><h3 id="來源" tabindex="-1">來源: <a class="header-anchor" href="#來源" aria-label="Permalink to “來源:”">​</a></h3>`,77)),e("ul",null,[e("li",null,[n(t,{href:"https://launchpad.net/sbackup"},{default:r(()=>[...p[0]||(p[0]=[a("https://launchpad.net/sbackup",-1)])]),_:1})]),e("li",null,[n(t,{href:"http://sourceforge.net/projects/sbackup/"},{default:r(()=>[...p[1]||(p[1]=[a("http://sourceforge.net/projects/sbackup/",-1)])]),_:1})])]),p[14]||(p[14]=e("hr",null,null,-1)),e("p",null,[p[3]||(p[3]=a("via: ",-1)),n(t,{href:"http://www.unixmen.com/linux-desktop-backup-made-easy-sbackup/"},{default:r(()=>[...p[2]||(p[2]=[a("http://www.unixmen.com/linux-desktop-backup-made-easy-sbackup/",-1)])]),_:1})]),e("p",null,[p[6]||(p[6]=a("譯者：",-1)),n(t,{href:"https://github.com/NearTan"},{default:r(()=>[...p[4]||(p[4]=[a("NearTan",-1)])]),_:1}),p[7]||(p[7]=a(" 校對：",-1)),n(t,{href:"https://github.com/carolinewuyan"},{default:r(()=>[...p[5]||(p[5]=[a("Caroline",-1)])]),_:1})]),e("p",null,[p[10]||(p[10]=a("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...p[8]||(p[8]=[a("LCTT",-1)])]),_:1}),p[11]||(p[11]=a(" 原創翻譯，",-1)),n(t,{href:"http://linux.cn/"},{default:r(()=>[...p[9]||(p[9]=[a("Linux中國",-1)])]),_:1}),p[12]||(p[12]=a(" 榮譽推出",-1))])])}const f=i(c,[["render",d]]);export{x as __pageData,f as default};
